"use strict";(globalThis.webpackChunkprotoflow_docs=globalThis.webpackChunkprotoflow_docs||[]).push([[581],{3664:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"courseSidebar":[{"type":"link","href":"/Wind-tunnel-book/","label":"Introduction","docId":"introduction/index","unlisted":false},{"type":"link","href":"/Wind-tunnel-book/fundamentals","label":"Wind Tunnel Fundamentals","docId":"fundamentals/index","unlisted":false},{"type":"link","href":"/Wind-tunnel-book/windtunnel","label":"The ProtoFlow Tunnel","docId":"windtunnel/index","unlisted":false},{"type":"link","href":"/Wind-tunnel-book/instrumentation","label":"Measurement Instruments","docId":"instrumentation/index","unlisted":false},{"type":"link","href":"/Wind-tunnel-book/operating","label":"Operating ProtoFlow","docId":"operating/index","unlisted":false},{"type":"link","href":"/Wind-tunnel-book/references/","label":"References","docId":"references/index","unlisted":false}],"refSidebar":[{"type":"link","href":"/Wind-tunnel-book/theory/aerodynamics","label":"Aerodynamics","docId":"theory/aerodynamics","unlisted":false},{"type":"link","href":"/Wind-tunnel-book/theory/pressure-network","label":"Wind tunnel model","docId":"theory/pressure-network","unlisted":false},{"type":"link","href":"/Wind-tunnel-book/theory/references","label":"References","docId":"theory/references","unlisted":false}]},"docs":{"fundamentals/index":{"id":"fundamentals/index","title":"Wind Tunnel Fundamentals","description":"This chapter introduces the physical principles that underpin wind tunnels. Understanding these concepts will help you in setting up and interpreting your measurements.","sidebar":"courseSidebar"},"instrumentation/index":{"id":"instrumentation/index","title":"Measurement Instruments","description":"","sidebar":"courseSidebar"},"introduction/index":{"id":"introduction/index","title":"Introduction","description":"Flows shape the performance of many engineered systems. They determine how much lift an aircraft produces and how efficiently a car moves through the air, but they are equally important in a wide range of mechanical engineering applications, including heat exchangers, ventilation systems, turbomachinery, energy systems, and electronic cooling. In many cases, the behavior of a fluid directly determines a system\'s efficiency, reliability, and operating limits.","sidebar":"courseSidebar"},"operating/index":{"id":"operating/index","title":"Operating ProtoFlow","description":"This chapter covers everything you need to conduct a safe and successful experiment: safety rules, prototype design guidelines, model mounting, running the tunnel, and acquiring data.","sidebar":"courseSidebar"},"references/index":{"id":"references/index","title":"References","description":"Barlow, J.B., Rae, W.H. & Pope, A. (1999). Low-Speed Wind Tunnel Testing, 3rd ed. John Wiley & Sons.","sidebar":"courseSidebar"},"theory/aerodynamics":{"id":"theory/aerodynamics","title":"Aerodynamics","description":"Turbulent friction","sidebar":"refSidebar"},"theory/pressure-network":{"id":"theory/pressure-network","title":"Wind tunnel model","description":"A one-dimensional flow model is developed to predict the flow rates in the various sections of the wind tunnel. In this one-dimensional model, the flow is characterized by the volumetric flow rates, $Qi$, in each section and the static pressure at each section interface, $pi$ (red nodes). Pressures and velocities represent spatial means over the cross-section area. Non-uniformities such as boundary layers, velocity deficits, and secondary flows are not resolved individually (Barlow et al., 1999).","sidebar":"refSidebar"},"theory/references":{"id":"theory/references","title":"References","description":"Barlow, J.B., Rae, W.H. & Pope, A. (1999). Low-Speed Wind Tunnel Testing, 3rd ed. John Wiley & Sons.","sidebar":"refSidebar"},"windtunnel/index":{"id":"windtunnel/index","title":"The ProtoFlow Tunnel","description":"This chapter describes the ProtoFlow wind tunnel: its layout, its components, and the design choices behind them.","sidebar":"courseSidebar"}}}}')}}]);